      <div v-if="errorMessage" class="admin-owner-state error"><strong>{{ $t('legacy.t_a56234453671') }}</strong><span>{{ errorMessage }}</span><button @click="loadData">{{ $t('legacy.t_0c9157b5bfac') }}</button></div>
      <div v-else class="table-wrap finance-review-table-wrap">
        <table>
          <thead><tr><th class="finance-check-cell"><input type="checkbox" :checked="allPendingSelected" :disabled="!pendingRows.length" @change="togglePendingPage"></th><th>{{ $t('legacy.t_32e88cf956f6') }}</th><th>{{ $t('legacy.t_114246450ff0') }}</th><th>{{ $t('legacy.t_d61f1eba334a') }}</th><th>{{ $t('legacy.t_3542cc1d606d') }}</th><th>{{ $t('legacy.t_058f511c98cf') }}</th><th>{{ $t('legacy.t_41ee43593eb7') }}</th><th>{{ $t('legacy.t_4feb65fa9683') }}</th><th>{{ $t('legacy.t_94007fdd6e4e') }}</th><th>{{ $t('legacy.t_f3ea6d345e2a') }}</th></tr></thead>
