              <td><strong>{{ row.transactionNo }}</strong><small>{{ row.receiptNo || $t('legacy.t_4842630ef72e') }}</small></td>
              <td>{{ row.projectName }}<small>{{ row.unitNo }}</small></td>
              <td>{{ row.payerName || '—' }}<small>{{ row.bankReference || '—' }}</small></td>
              <td><b>{{ row.currency || 'MYR' }} {{ money(row.amount) }}</b></td>
              <td>{{ row.transactionDate || '—' }}</td>
              <td><button class="finance-proof-link" :disabled="!row.proofDocumentId" @click.stop="selectAndOpenProof(row)">{{ row.proofDocumentId ? $t('legacy.t_16194d3fdaa8') : $t('legacy.t_08f9d55c4a07') }}</button></td>
              <td><span class="tag" :class="confirmationClass(row.confirmationStatus)">{{ confirmationLabel(row.confirmationStatus) }}</span></td>
              <td><span class="tag" :class="syncClass(row.syncStatus)">{{ syncLabel(row.syncStatus) }}</span></td>
              <td><div v-if="viewMode === 'history'" class="finance-document-actions"><a :href="documentUrl(row, 'invoice')" download @click.stop>Invoice / 发票</a><a :href="documentUrl(row, 'receipt')" download @click.stop>Official Receipt / 收据</a></div><button v-else class="row-actions" @click.stop="selectRow(row)">…</button></td>
            </tr>
            <tr v-if="!loading && !rows.length"><td colspan="10" class="admin-owner-empty">{{ $t('legacy.t_43c0d81f0705') }}</td></tr>
          </tbody>
        </table>
      </div>
      <div class="pager"><span>{{ $t('legacy.t_3b6ef811b85a') }} {{ totalRows }} {{ $t('legacy.t_86761b63a7bd') }}</span><div class="admin-building-pager"><button :disabled="pageNumber <= 1" @click="goPage(pageNumber - 1)">&lt;</button><button v-for="n in visiblePages" :key="n" :class="{ active: n === pageNumber }" @click="goPage(n)">{{ n }}</button><button :disabled="pageNumber >= totalPages" @click="goPage(pageNumber + 1)">&gt;</button><select v-model.number="pageSize"><option :value="10">{{ $t('legacy.t_fc6da0e815a1') }}</option><option :value="20">{{ $t('legacy.t_93d673672fa5') }}</option><option :value="50">{{ $t('legacy.t_529930b886d2') }}</option></select></div></div>
    </div>

    <aside class="panel detail-panel finance-review-detail">
      <div v-if="selectedRow" class="detail-card">
        <div class="profile finance-review-profile"><div class="big-avatar">{{ $t('legacy.t_aab9b3921100') }}</div><div class="finance-review-profile-copy"><h3>{{ selectedRow.transactionNo }}</h3><p>{{ selectedRow.projectName }} · {{ selectedRow.unitNo }}</p></div><span class="tag" :class="confirmationClass(selectedRow.confirmationStatus)">{{ confirmationLabel(selectedRow.confirmationStatus) }}</span></div>
        <div class="detail-actions finance-review-actions">
          <button :disabled="!selectedRow.proofDocumentId" @click="openProof">{{ $t('legacy.t_96bd7ca72147') }}</button>
          <a v-if="viewMode === 'history'" class="finance-document-button" :href="documentUrl(selectedRow, 'invoice')" download>Invoice / 发票</a>
          <a v-if="viewMode === 'history'" class="finance-document-button" :href="documentUrl(selectedRow, 'receipt')" download>Official Receipt / 收据</a>
          <button v-if="selectedRow.confirmationStatus === 'pending'" class="confirm" @click="openDecision(true)">{{ $t('legacy.t_813b101df66f') }}</button>
          <button v-if="selectedRow.confirmationStatus === 'pending'" class="reject" @click="openDecision(false)">{{ $t('legacy.t_f21a4e73212a') }}</button>
        </div>
        <div class="detail-section"><h4><span class="num">{{ $t('legacy.t_356a192b7913') }}</span>{{ $t('legacy.t_82c8aa737dd5') }}</h4><div class="kv"><span>{{ $t('legacy.t_d61f1eba334a') }}</span><b>{{ selectedRow.payerName || '—' }}</b></div><div class="kv"><span>{{ $t('legacy.t_c6b9a8cfdb21') }}</span><b>{{ paymentMethodLabel(selectedRow.paymentMethod) }}</b></div><div class="kv"><span>{{ $t('legacy.t_bf8928021bb1') }}</span><b>{{ selectedRow.bankReference || '—' }}</b></div><div class="kv"><span>{{ $t('legacy.t_3542cc1d606d') }}</span><b>{{ selectedRow.currency }} {{ money(selectedRow.amount) }}</b></div></div>
        <div class="detail-section"><h4><span class="num">{{ $t('legacy.t_da4b9237bacc') }}</span>{{ $t('legacy.t_1efb9c79ecf7') }}</h4><div class="kv"><span>{{ $t('legacy.t_3d5edc260de1') }}</span><b>{{ $t('legacy.t_5e7b60c626a4') }} {{ money(selectedRow.accountBalance) }}</b></div><div class="kv"><span>{{ $t('legacy.t_c7e82f3b6404') }}</span><b>{{ $t('legacy.t_5e7b60c626a4') }} {{ money(selectedRow.accountMinimumBalance) }}</b></div><div class="kv"><span>{{ $t('legacy.t_0e267b2bee08') }}</span><b class="reserve-after">{{ $t('legacy.t_5e7b60c626a4') }} {{ money(Number(selectedRow.accountBalance || 0) + (selectedRow.confirmationStatus === 'pending' ? Number(selectedRow.amount || 0) : 0)) }}</b></div></div>
        <div class="detail-section"><h4><span class="num">{{ $t('legacy.t_77de68daecd8') }}</span>{{ $t('legacy.t_544d471b0705') }}</h4><div class="kv"><span>{{ $t('legacy.t_e2339796356e') }}</span><b>{{ selectedRow.proofName || $t('legacy.t_08f9d55c4a07') }}</b></div><div class="kv"><span>{{ $t('legacy.t_bffa37080afa') }}</span><b>{{ selectedRow.confirmedByName || '—' }}</b></div><div class="kv"><span>{{ $t('legacy.t_2d36c3ab208f') }}</span><b>{{ dateTime(selectedRow.confirmedAt) }}</b></div><div class="kv"><span>{{ $t('legacy.t_098de965a383') }}</span><b>{{ selectedRow.reviewNote || '—' }}</b></div></div>
      </div>
      <div v-else class="admin-owner-empty">{{ $t('legacy.t_58e738462315') }}</div>
    </aside>

    <dialog ref="decisionDialog" class="modal admin-finance-decision-dialog"><form method="dialog" @submit.prevent="submitDecision"><div class="modal-head"><div><h3>{{ approving ? $t('legacy.t_d4c367acb3b4') : $t('legacy.t_6daef0b6e930') }}</h3><small>{{ selectedRow?.transactionNo }} {{ $t('legacy.t_6287ccc52c97') }} {{ money(selectedRow?.amount) }}</small></div><button type="button" class="icon-close" @click="closeDecision">×</button></div><div class="finance-decision-body"><div :class="['finance-decision-warning', { success: approving }]"><strong>{{ approving ? $t('legacy.t_f4e8b8b461db') : $t('legacy.t_ec6e1980eaf8') }}</strong><span>{{ approving ? `賬戶餘額將增加 RM ${money(selectedRow?.amount)}` : $t('legacy.t_2f5741d5285b') }}</span></div><label>{{ $t('legacy.t_098de965a383') }}<textarea v-model.trim="decisionNote" maxlength="500" required :placeholder="approving ? $t('legacy.t_c333960469a4') : $t('legacy.t_f8c08ef26a07')"></textarea></label><p v-if="actionError" class="admin-property-error">{{ actionError }}</p></div><menu><button type="button" @click="closeDecision">{{ $t('legacy.t_4d0b4688c787') }}</button><button class="primary-btn" :class="{ reject: !approving }" :disabled="actionSaving">{{ actionSaving ? $t('legacy.t_1e038f9b55ec') : approving ? $t('legacy.t_37786d40f2c5') : $t('legacy.t_559f15fd1a6a') }}</button></menu></form></dialog>

    <dialog ref="batchDialog" class="modal admin-finance-decision-dialog"><form method="dialog" @submit.prevent="submitBatch"><div class="modal-head"><div><h3>{{ $t('legacy.t_6bdd44210e06') }}</h3><small>{{ $t('legacy.t_aeec0b67da9d') }} {{ selectedIds.length }} {{ $t('legacy.t_a0083f38e86d') }}</small></div><button type="button" class="icon-close" @click="closeBatch">×</button></div><div class="finance-decision-body"><div class="finance-decision-warning success"><strong>{{ $t('legacy.t_b266705f45bb') }}</strong><span>{{ $t('legacy.t_c583036384b4') }}</span></div><label>{{ $t('legacy.t_c5dc4a6f6bc8') }}<textarea v-model.trim="batchNote" maxlength="500" required></textarea></label><p v-if="actionError" class="admin-property-error">{{ actionError }}</p></div><menu><button type="button" @click="closeBatch">{{ $t('legacy.t_4d0b4688c787') }}</button><button class="primary-btn" :disabled="actionSaving">{{ actionSaving ? $t('legacy.t_03fc655d6daf') : `確認 ${selectedIds.length} 筆充值` }}</button></menu></form></dialog>

    <dialog ref="proofDialog" class="modal admin-finance-proof-dialog"><div class="modal-head"><div><h3>{{ $t('legacy.t_849b273896de') }}</h3><small>{{ selectedRow?.proofName || selectedRow?.transactionNo }}</small></div><button type="button" class="icon-close" @click="closeProof">×</button></div><div class="finance-proof-viewer"><div v-if="proofLoading" class="admin-owner-state">{{ $t('legacy.t_38e6a8f0a0f3') }}</div><img v-else-if="proofUrl && selectedRow?.proofMimeType?.startsWith('image/')" :src="proofUrl" :alt="$t('legacy.t_849b273896de')"><iframe v-else-if="proofUrl && selectedRow?.proofMimeType === 'application/pdf'" :src="proofUrl" :title="$t('legacy.t_32540522e657')"></iframe><div v-else class="admin-owner-state">{{ proofError || $t('legacy.t_410b7e2a33ff') }}</div></div><menu><button @click="closeProof">{{ $t('legacy.t_ddc05404b0d6') }}</button><button class="primary-btn" :disabled="!selectedRow?.proofDocumentId" @click="downloadProof">{{ $t('legacy.t_fb332e3c9ee6') }}</button></menu></dialog>
  </section>
</template>

<script>
import { batchConfirmAdminReserveTopups, downloadAdminFinanceDocuments, fetchAdminFinanceProjects, fetchAdminFinanceReviews, fetchAdminReserveProof, getAdminFinanceDocumentUrl, reviewAdminReserveTopup } from '../services/propertyApi';

export default {
  inject: ['page'],
  data() { return { rows: [], selectedId: null, selectedIds: [], pageNumber: 1, pageSize: 10, totalRows: 0, totalPages: 1, loading: false, errorMessage: '', serial: 0, approving: true, decisionNote: '', batchNote: '銀行入賬與充值憑證核對一致', actionSaving: false, actionError: '', proofLoading: false, proofError: '', proofUrl: '' }; },
  computed: {
    selectedRow() { return this.rows.find(row => row.id === this.selectedId) || this.rows[0] || null; },
    viewMode() { return this.page.adminFinanceViewMode === 'history' ? 'history' : 'pending'; },
    pendingRows() { return this.rows.filter(row => row.confirmationStatus === 'pending'); },
    allPendingSelected() { return this.pendingRows.length > 0 && this.pendingRows.every(row => this.selectedIds.includes(row.id)); },
    visiblePages() { const start = Math.max(1, Math.min(this.pageNumber - 2, this.totalPages - 4)); return Array.from({ length: Math.min(5, this.totalPages) }, (_, i) => start + i); },
    batchNonce() { return this.page.adminFinanceBatchNonce; }, refreshNonce() { return this.page.adminFinanceRefreshNonce; }
  },
  watch: {
    'page.moduleSearch'() { this.resetLoad(); }, 'page.globalSearch'() { this.resetLoad(); }, 'page.projectFilter'() { this.resetLoad(); }, 'page.statusFilter'() { this.resetLoad(); }, 'page.adminFinanceViewMode'() { this.resetLoad(); }, 'page.dateStart'() { this.resetLoad(); }, 'page.dateEnd'() { this.resetLoad(); }, pageSize() { this.resetLoad(); },
    batchNonce(v, old) { if (v > old) this.openBatch(); }, refreshNonce(v, old) { if (v > old) this.loadData(); },
    rows: { deep: true, handler(rows) { if (!rows.some(row => row.id === this.selectedId)) this.selectedId = rows[0]?.id || null; } }
  },
  mounted() { this.loadData(); }, beforeUnmount() { this.revokeProof(); },
  methods: {
    async loadData() { const serial = ++this.serial; this.loading = true; this.errorMessage = ''; try { const params = { type: 'reserve', page: this.pageNumber, pageSize: this.pageSize, keyword: this.page.globalSearch || this.page.moduleSearch || '', projectName: String(this.page.projectFilter || '').includes('全部') ? '' : this.page.projectFilter, status: this.requestStatus(), startDate: this.page.dateStart, endDate: this.page.dateEnd }; const [response, projects] = await Promise.all([fetchAdminFinanceReviews(params), fetchAdminFinanceProjects('reserve')]); if (serial !== this.serial) return; this.rows = response.rows || []; this.totalRows = response.page?.totalRows || 0; this.totalPages = response.page?.totalPages || 1; this.pageNumber = response.page?.page || 1; this.page.adminFinanceProjects = projects || []; this.page.adminFinanceMetrics = this.metrics(response.summary || {}); this.selectedIds = this.selectedIds.filter(id => this.pendingRows.some(row => row.id === id)); } catch (error) { if (serial !== this.serial) return; this.rows = []; this.errorMessage = error.message || 'API request failed'; this.page.adminFinanceMetrics = null; } finally { if (serial === this.serial) this.loading = false; } },
    metrics(s) { return [{ label: '待確認充值', value: `${Number(s.pendingCount || 0)} 筆`, delta: `RM ${this.money(s.pendingAmount)}`, trend: Number(s.pendingCount) ? 'down' : 'up' }, { label: '已確認充值', value: `${Number(s.confirmedCount || 0)} 筆`, delta: '已增加預備金', trend: 'up' }, { label: '已退回申請', value: `${Number(s.rejectedCount || 0)} 筆`, delta: '保留退回原因', trend: Number(s.rejectedCount) ? 'down' : 'up' }, { label: '待同步 SQL', value: `${Number(s.pendingSyncCount || 0)} 筆`, delta: '會計同步狀態', trend: Number(s.pendingSyncCount) ? 'down' : 'up' }, { label: '本月確認充值', value: `RM ${this.money(s.confirmedMonthAmount)}`, delta: '本月實際入賬', trend: 'up' }]; },
    resetLoad() { this.pageNumber = 1; this.selectedIds = []; this.loadData(); }, goPage(n) { if (n >= 1 && n <= this.totalPages && n !== this.pageNumber) { this.pageNumber = n; this.loadData(); } }, selectRow(row) { this.selectedId = row.id; }, documentUrl(row, type) { return row?.id ? getAdminFinanceDocumentUrl(row.id, type) : '#'; }, async batchDownload(type) { const ids = this.rows.map(row => row.id).filter(Boolean); if (!ids.length) { this.page.showToast('当前没有可下载的历史记录'); return; } try { const result = await downloadAdminFinanceDocuments(ids, type); const url = URL.createObjectURL(result.blob); const link = document.createElement('a'); link.href = url; link.download = result.filename; document.body.appendChild(link); link.click(); link.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); this.page.showToast(`已生成 ${ids.length} 份${type === 'invoice' ? '发票' : '收据'}`); } catch (error) { this.page.showToast(error.message || '批量下载失败'); } },
    togglePendingPage(event) { const ids = this.pendingRows.map(row => row.id); this.selectedIds = event.target.checked ? [...new Set([...this.selectedIds, ...ids])] : this.selectedIds.filter(id => !ids.includes(id)); },
    openDecision(approved) { this.approving = approved; this.decisionNote = approved ? '銀行入賬與充值憑證核對一致' : ''; this.actionError = ''; this.$refs.decisionDialog?.showModal(); }, closeDecision() { this.$refs.decisionDialog?.close(); },
    async submitDecision() { if (!this.decisionNote) { this.actionError = '請填寫審核備註'; return; } this.actionSaving = true; this.actionError = ''; try { await reviewAdminReserveTopup(this.selectedRow.id, this.approving, this.decisionNote); this.closeDecision(); await this.loadData(); this.page.showToast(this.approving ? '預備金充值已確認並入賬' : '充值申請已退回'); } catch (error) { this.actionError = error.message || '充值審核失敗'; } finally { this.actionSaving = false; } },
    openBatch() { if (!this.selectedIds.length) { this.page.showToast('請先勾選待確認充值'); return; } this.actionError = ''; this.$refs.batchDialog?.showModal(); }, closeBatch() { this.$refs.batchDialog?.close(); }, async submitBatch() { if (!this.batchNote) return; this.actionSaving = true; this.actionError = ''; const count = this.selectedIds.length; try { await batchConfirmAdminReserveTopups(this.selectedIds, this.batchNote); this.closeBatch(); this.selectedIds = []; await this.loadData(); this.page.showToast(`已確認 ${count} 筆預備金充值`); } catch (error) { this.actionError = error.message || '批量確認失敗'; } finally { this.actionSaving = false; } },
    selectAndOpenProof(row) { this.selectRow(row); this.$nextTick(this.openProof); }, async openProof() { if (!this.selectedRow?.proofDocumentId) return; this.revokeProof(); this.proofLoading = true; this.proofError = ''; this.$refs.proofDialog?.showModal(); try { const result = await fetchAdminReserveProof(this.selectedRow.proofDocumentId); this.proofUrl = URL.createObjectURL(result.blob); } catch (error) { this.proofError = error.message || '憑證載入失敗'; } finally { this.proofLoading = false; } }, closeProof() { this.$refs.proofDialog?.close(); this.revokeProof(); }, revokeProof() { if (this.proofUrl) URL.revokeObjectURL(this.proofUrl); this.proofUrl = ''; }, async downloadProof() { try { const result = await fetchAdminReserveProof(this.selectedRow.proofDocumentId, true); const url = URL.createObjectURL(result.blob); const link = document.createElement('a'); link.href = url; link.download = this.selectedRow.proofName || `reserve-proof-${this.selectedRow.id}`; link.click(); URL.revokeObjectURL(url); } catch (error) { this.page.showToast(error.message || '憑證下載失敗'); } },
    statusParam(v) { return ({ '待確認': 'pending', '已確認': 'confirmed', '已退回': 'rejected', '待同步': 'sync_pending', '同步失敗': 'sync_failed' })[v] || ''; }, requestStatus() { if (this.viewMode === 'pending') return 'pending'; return this.statusParam(this.page.statusFilter) || 'history'; }, confirmationLabel(v) { return ({ pending: '待確認', confirmed: '已確認', rejected: '已退回' })[v] || '未知'; }, confirmationClass(v) { return v === 'confirmed' ? 'green' : v === 'rejected' ? 'red' : 'orange'; }, syncLabel(v) { return ({ not_synced: '未同步', pending: '待同步', synced: '已同步', failed: '同步失敗' })[v] || '未同步'; }, syncClass(v) { return v === 'synced' ? 'green' : v === 'failed' ? 'red' : 'orange'; }, paymentMethodLabel(v) { return ({ bank_transfer: '銀行轉賬', online_payment: '線上支付' })[v] || v || '—'; }, dateTime(v) { return v ? String(v).replace('T', ' ').slice(0, 19) : '—'; }, money(v) { return Number(v || 0).toLocaleString('en-MY', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
  }
};
</script>

<style scoped>
.admin-reserve-finance-workspace { align-items: stretch; }.admin-reserve-finance-workspace .finance-review-panel,.admin-reserve-finance-workspace .finance-review-detail { min-height: 590px; }.admin-reserve-finance-workspace td small { display: block; margin-top: 3px; color: #7b8798; font-size: 9px; }.reserve-after { color: #15803d !important; }
</style>
<style scoped>
.finance-document-actions{display:grid;gap:4px;min-width:106px}.finance-document-actions a,.finance-document-button{display:inline-flex;align-items:center;justify-content:center;min-height:26px;padding:0 7px;border:1px solid #b7cfee;border-radius:6px;background:#f7fbff;color:#185a97;font-size:10px;text-decoration:none;white-space:nowrap}.finance-document-actions a:hover,.finance-document-button:hover{background:#eaf3ff;border-color:#6f9fda}
